//! `shim-differential` — the worked differential, on stdout.
//!
//! # Why a second binary and not a test
//!
//! The deliverable is a **pair of recordings and an analysis**, and a test
//! asserts a property rather than producing a document an analyst can read. So
//! the artefact is generated by a binary and committed, and a test checks that
//! the committed bytes are what the binary prints today — the same arrangement
//! `shim-record` and `recordings/synthetic.recording.json` use, for the same
//! reason.
//!
//! # stdout, not files
//!
//! Same constraint as `shim-record`, and for the same reason: this crate's
//! `std::fs` surface is empty, and `tests/egress_denial.rs` proves it by
//! scanning the source. Printing is how a recording leaves the process.
//!
//! # What it prints
//!
//! ```text
//! ==== left arm: <digest> ====
//! <document>
//! ==== right arm: <digest> ====
//! <document>
//! ==== report ====
//! <the attribution table>
//! ```
//!
//! The two documents are exactly the two committed files, so the report can be
//! reproduced from them alone with `shim::differential::diff`.

use std::process::ExitCode;

fn main() -> ExitCode {
    let (left, right) = shim::differential::committed_policies();
    let arms = match shim::differential::two_arms(left, right) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("shim-differential: the arms could not be produced: {e}");
            return ExitCode::from(1);
        }
    };
    let report = match shim::differential::diff(&arms.0.document, &arms.1.document) {
        Ok(d) => d.report(),
        Err(e) => {
            eprintln!("shim-differential: the arms could not be diffed: {e}");
            return ExitCode::from(1);
        }
    };

    let mut out = String::new();
    for (arm, tag) in [(&arms.0, "left"), (&arms.1, "right")] {
        let rendered = match serde_json::to_string_pretty(&arm.document) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("shim-differential: an arm did not serialise: {e}");
                return ExitCode::from(1);
            }
        };
        // The same last gate `shim-record` has. A policy axis must not become a
        // way to get a secret into a recording.
        if let Err(v) = shim::redact::scrub(&rendered, &[]) {
            eprintln!("shim-differential: REFUSING TO EMIT: an arm violates the privacy policy");
            for violation in v {
                eprintln!("  at {}: {}", violation.at, violation.what);
            }
            return ExitCode::from(2);
        }
        out.push_str(&format!(
            "==== {tag} arm: {} ({}) ====\n",
            arm.policy.digest(),
            shim::differential::arm_label(&arm.policy)
        ));
        out.push_str(&rendered);
        out.push('\n');
    }
    out.push_str("==== report ====\n");
    out.push_str(&report);
    println!("{out}");
    ExitCode::SUCCESS
}
